) -> RetrievalOutcome:
    if not self.rag_config.enabled or not query:
        return RetrievalOutcome(chunks=[])
    filters: dict | None = None
    if document_ids is not None:
        filters = {"document_ids": document_ids, "owner_scoped": True}
