        RetrievalRequest(
            query=query,
            user_id=user_id,
            project_id=project_id,
            top_k=top_k,
            filters=filters,
        )
    )

def rerank(
    self,
    query: str,
    chunks: list[RetrievedChunk],
    *,
    limit: int,
) -> list[RetrievedChunk]:
    terms = set(_UNICODE_TOKEN.findall(query.lower()))
    if not terms or len(chunks) < MIN_RERANK_CANDIDATES:
        return chunks[:limit]

    def key(chunk: RetrievedChunk) -> tuple[float, float, int]:
        content_terms = set(_UNICODE_TOKEN.findall(chunk.content.lower()))
        overlap = len(terms & content_terms) / len(terms)
        # Sort by overlap first, then original score, then original rank.
        return (overlap, chunk.score, -(chunk.rank or 0))

    return sorted(chunks, key=key, reverse=True)[:limit]

def _coverage_for_chunks(
    chunks: list[RetrievedChunk], document_ids: list[str] | None
) -> RetrievalCoverage:
    documents_in_scope = len(document_ids) if document_ids is not None else 0
    documents_with_evidence = len({chunk.document_id for chunk in chunks})
    coverage_ratio = documents_with_evidence / documents_in_scope if documents_in_scope else 0.0
    return RetrievalCoverage(
        documents_in_scope=documents_in_scope,
        documents_with_retrieved_evidence=documents_with_evidence,
        retrieved_passage_count=len(chunks),
        coverage_ratio=coverage_ratio,
    )

def ranking_metrics_from_fixture(
    ranked_ids: list[str],
    relevant_ids: set[str],
    *,
    k: int = 5,
) -> dict[str, float]:
    """Compute Recall@k / MRR from synthetic fixture rankings (no live retrieval)."""
    return {
        "recall_at_k": recall_at_k(ranked_ids, relevant_ids, k=k),
        "mrr": mean_reciprocal_rank(ranked_ids, relevant_ids),
    }

def ndcg_at_k(predicted: list[str], relevance: dict[str, float], k: int) -> float:
    def dcg(items: list[str]) -> float:
        return sum(
            (2 ** relevance.get(item, 0.0) - 1) / math.log2(rank + 1)
            for rank, item in enumerate(items, start=1)
        )

    actual = dcg(predicted[:k])
    ideal = dcg(sorted(relevance, key=relevance.get, reverse=True)[:k])
    return actual / ideal if ideal else 1.0

def _chunks_from_ids(ranked_ids: list[str]) -> list[RetrievedChunk]:
    return [
        RetrievedChunk(
            chunk_id=chunk_id,
            document_id=chunk_id.split("#", 1)[0],
            content=chunk_id,
            score=1.0 - (index * 0.01),
            filename=f"{chunk_id}.txt",
            chunk_index=index,
        )
        for index, chunk_id in enumerate(ranked_ids)
    ]

def _bbox_values(value: Any) -> tuple[tuple[float, float, float, float] | None, str | None]:
    if value is None:
        return None, None
    try:
        box = (
            float(value.l),
            float(value.t),
            float(value.r),
            float(value.b),
        )
    except (AttributeError, TypeError, ValueError):
        return None, None
    origin = _enum_value(getattr(value, "coord_origin", "unknown"))
    origin_name = {"topleft": "top_left", "bottomleft": "bottom_left"}.get(origin)
    coordinate_system = f"page_points_{origin_name}" if origin_name else "page_points_unknown"
    return box, coordinate_system

def _attrs(kwargs: dict[str, Any]) -> dict[str, Any]:
    attrs: dict[str, Any] = {}
    for key, value in kwargs.items():
        if value is None:
            continue
        attr = key.replace("_", ".")
        if isinstance(value, str | bool | int | float):
            attrs[attr] = value
        else:
            attrs[attr] = str(value)
    return attrs

