export function FormField({ label, description, error, id, ...props }: ControlProps) {
    const generatedId = useId();
    const controlId = id ?? generatedId;
    const messageId = description ? `${controlId}-message` : undefined;
    const ids = [props["aria-describedby"], messageId].filter(Boolean).join(" ").trim().split(/\s+/);
    const invalid = error || props["aria-invalid"];
    return <Field data-invalid={invalid}>{label && <FieldLabel htmlFor={controlId}>{label}</FieldLabel>}<Control {...props} id={controlId} aria-describedby={[...new Set(ids)].join(" ") || undefined} aria-invalid={invalid} />{description && (error ? <FieldError id={messageId}>{description}</FieldError> : <FieldDescription id={messageId}>{description}</FieldDescription>)}</Field>;
}

describe("jsonDisplay helpers", () => {
    it("formats nested values without dumping full JSON", () => {
        expect(formatDisplayValue({ a: 1, b: 2 })).toBe("{a, b}");
        expect(formatDisplayValue(["x", "y"])).toBe("x, y");
        expect(formatDisplayValue([{ id: 1 }, { id: 2 }])).toBe("2 items");
    });

    it("flattens records for key/value lists", () => {
        expect(recordToKeyValueItems({ train_size: 80, seed: 7 })).toEqual([
            { key: "train_size", label: "train size", value: "80" },
            { key: "seed", label: "seed", value: "7" },
        ]);
        expect(stringifyPretty({ a: 1 })).toContain('"a": 1');
    });
});

export function recordToKeyValueItems(
    data: unknown,
    options?: { maxEntries?: number }
): JsonKeyValueItem[] {
    if (!data || typeof data !== "object" || Array.isArray(data)) return [];
    const max = options?.maxEntries ?? 24;
    return Object.entries(data as Record<string, unknown>)
        .slice(0, max)
        .map(([key, value]) => ({
            key,
            label: key.replaceAll("_", " "),
            value: formatDisplayValue(value),
        }));
}

